#!/usr/bin/env bash
set -euo pipefail
ADB=${ADB:-adb}; D=/data/local/tmp; C="$D/.c"
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT INT TERM
extract(){ awk "/^__PAYLOAD_$1__/{f=1;next}/^__END_PAYLOAD_$1__/{exit}f" "$0" | base64 -d > "$TMP/$2"; }
extract P p_latest
extract DEX ov_new.dex
extract GPNG glyph.png
extract GTXT glyph.txt
extract UIPNG ov_ui.png
extract UITXT ov_ui.txt
extract CTYPE ov_ctype.txt
extract LEVEL ov_level.txt
extract NAME ov_name.txt
extract PRICE ov_price.txt
extract SKIP ov_skip.txt
for f in p_latest ov_new.dex glyph.png glyph.txt ov_ui.png ov_ui.txt ov_ctype.txt ov_level.txt ov_name.txt ov_price.txt ov_skip.txt; do
  "$ADB" push "$TMP/$f" "$D/$f" >/dev/null
done
"$ADB" shell "su -c 'mkdir -p $C; chmod 755 $D/p_latest; echo 1 > $D/ov_dec.txt; echo 0 > $D/ov_dec2.txt; echo 0 > $D/ov_dec3.txt; echo 1 > $D/ov_dec4.txt; chmod 666 $D/ov_dec*.txt; for x in /proc/[0-9]*; do e=\$(readlink \$x/exe 2>/dev/null); case "\$e" in */.c/p*) kill -9 \${x#/proc/} 2>/dev/null;; esac; done; sleep 2; rm -f $C/pt; cp $D/p_latest $C/pt; mv -f $C/pt $C/p; chmod 755 $C/p; setsid sh -c "exec $C/p > $C/p.log 2>&1" < /dev/null &; sleep 2; pkill -9 -f Ov50 2>/dev/null || true; sleep 2; rm -f $C/oz.dex; cp $D/ov_new.dex $C/oz.dex; mv -f $C/oz.dex $C/o.dex; chmod 644 $C/o.dex; cd $D; setsid sh -c "CLASSPATH=$C/o.dex exec app_process $D Ov50 2414 1080 0 0 > $C/o.log 2>&1" < /dev/null &; sleep 4; tail -2 $C/o.log'"
echo "process started; driver must already be loaded"
exit 0

